#!/usr/bin/env node
// Generates docs/REPO-MAP.md -- a ~1k-token orientation map (routes, models,
// lib exports, shared components) so sessions get O(1) orientation instead of
// O(files) exploratory reads (ADR-019; aider repo-map pattern, sized down).
// Regenerated by the SessionStart hook when schema/app/lib are newer than the map.
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { join, relative } from "node:path";

const root = process.cwd();
const out = ["# Repo map (generated -- do not edit; `node scripts/repo-map.mjs`)", ""];
// Precompiled once (not per route file): method -> its export-detector regex.
const HTTP_METHOD_RES = "GET POST PUT PATCH DELETE".split(" ").map((m) => [m, new RegExp(`export const ${m}\\b`)]);

function walk(dir, fn) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) walk(p, fn);
    else fn(p);
  }
}

// API routes + pages
out.push("## Routes (app/)");
const routes = [];
walk(join(root, "app"), (p) => {
  const rel = relative(root, p);
  if (/\/(route|page)\.tsx?$/.test(rel)) {
    let methods = "";
    if (rel.endsWith("route.ts")) {
      const src = readFileSync(p, "utf8");
      methods = HTTP_METHOD_RES.filter(([, re]) => re.test(src)).map(([m]) => m).join(",");
    }
    routes.push(`- ${rel}${methods ? `  [${methods}]` : ""}`);
  }
});
out.push(...routes.sort(), "");

// Prisma models
out.push("## Models (prisma/schema.prisma)");
const schema = readFileSync(join(root, "prisma/schema.prisma"), "utf8");
for (const m of schema.matchAll(/^model (\w+) \{([^}]*)\}/gms)) {
  const fields = [...m[2].matchAll(/^\s{2}(\w+)\s+(\S+)/gm)]
    .map((f) => f[1]).filter((f) => !f.startsWith("@@"));
  out.push(`- ${m[1]}: ${fields.join(", ")}`);
}
out.push("");

// lib exports
out.push("## lib/ exports");
walk(join(root, "lib"), (p) => {
  if (!p.endsWith(".ts")) return;
  const names = [...readFileSync(p, "utf8")
    .matchAll(/^export (?:async )?(?:function|const|class|type|interface) (\w+)/gm)]
    .map((m) => m[1]);
  if (names.length) out.push(`- ${relative(root, p)}: ${names.join(", ")}`);
});
out.push("");

// shared components
out.push("## components/");
walk(join(root, "components"), (p) => {
  if (p.endsWith(".tsx")) out.push(`- ${relative(root, p)}`);
});

writeFileSync(join(root, "docs/REPO-MAP.md"), out.join("\n") + "\n");
console.log(`repo-map: ${out.length} lines -> docs/REPO-MAP.md`);
